import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, ShieldCheck } from 'lucide-react';

export default function LoginPage({ onLogin }) {
  const [email, setEmail] = useState('');
  const [name, setName] = useState('SecOps Analyst');
  const navigate = useNavigate();

  const handleGoogleAuthSimulation = (e) => {
    e.preventDefault();
    if (!email) return;
    const userData = { name, email };
    onLogin(userData);
    localStorage.setItem('netsentinel_user', JSON.stringify(userData));
    navigate('/dashboard');
  };

  return (
    <div style={{ maxWidth: '420px', margin: '60px auto', padding: '0 20px' }}>
      <div className="cyber-card">
        <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <ShieldCheck size={36} color="var(--accent-cyan)" />
          <h2 style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)', marginTop: '10px' }}>
            SECURE AUTHENTICATION
          </h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '13px', marginTop: '6px' }}>
            Sign in to initialize secure search history and persist scan reports.
          </p>
        </div>

        <form onSubmit={handleGoogleAuthSimulation} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div>
            <label style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--accent-cyan)', display: 'block', marginBottom: '6px' }}>
              ANALYST NAME:
            </label>
            <input 
              type="text" 
              className="cyber-input" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              required 
            />
          </div>

          <div>
            <label style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--accent-cyan)', display: 'block', marginBottom: '6px' }}>
              WORK EMAIL / GOOGLE ID:
            </label>
            <input 
              type="email" 
              className="cyber-input" 
              placeholder="analyst@domain.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required 
            />
          </div>

          <button type="submit" className="cyber-button" style={{ width: '100%', marginTop: '10px' }}>
            <User size={16} /> CONTINUE WITH GOOGLE AUTH
          </button>
        </form>
      </div>
    </div>
  );
}
